(* HMI status lamps — update at end of scan *)
Ready_Lamp   := NOT Fault_State AND NOT Running;
Running_Lamp := Running AND NOT Fault_State;
Fault_Lamp   := Fault_State;
Step_Display := Step_State;   (* INT → HMI numeric display *)

(* Alarm beacon — flashing handled by HMI, we just send the bit *)
Alarm_Beacon := Fault_State OR High_High_Alarm OR Low_Low_Alarm;
